faq=pagehero('A LITTLE MORE CLARITY','Your Questions, Answered','Helpful information before your first enquiry.')+'<section class="section container narrow prose">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faqs)+'</section>'
policies={
'privacy-policy.html':('Privacy Policy', [('About this preview','This is a frontend demonstration. No enquiry is submitted to a server by this site. The business must approve its final privacy notice before production.'),('Your cart','Only meal identifiers and quantities are saved in browser localStorage. Clear your cart or browser site data to remove them. Contact details are not saved locally.'),('Enquiries','Contact form details are used to prepare a WhatsApp link. Information is shared with WhatsApp and the recipient only when you choose to open and send the message. WhatsApp’s own privacy terms apply.'),('External services','Phone and maps links open services outside this website. Google Fonts may receive standard network information when fonts load. No analytics or advertising tools are configured.'),('Contact and data requests','Call +91 7529973199 for questions about information you send to the business. Production retention periods, the responsible legal entity and a formal privacy contact remain to be confirmed.')]),
 'terms-and-conditions.html':('Terms & Conditions',[('Status of this website','This is a demonstration and the terms are an unapproved preview. Sample prices, photography, meal descriptions and subscription options are not confirmed offers.'),('Order confirmation','A cart or enquiry does not form an order. Confirm the current menu, pricing, taxes, fees, ingredients, availability, service location and schedule with the business before agreeing to a purchase.'),('Meals and allergens','Photographs are illustrative. Confirm portion sizes, substitutions, allergens and cross-contact handling before ordering. No therapeutic or guaranteed health outcomes are promised.'),('Subscriptions','Meal frequency, service days, pause policies, exclusions and cancellation terms require written confirmation. The annual plan requires a separate approved agreement; payment is disabled.'),('Outstanding production details','The legal business name, registration details where applicable, operating hours, grievance contact, service policies and jurisdiction must be supplied and reviewed before launch.'),('Questions','Contact Diet Food Wala at Shop No. 1, CCB Complex, Near Jagdamba Public School, Jaitpur, New Delhi – 110044, or call +91 7529973199.')]),
 'refund-policy.html':('Refund Policy',[('Preview only','No payments or orders are processed on this website. This policy has not yet been approved by the business and does not establish a refund entitlement.'),('Individual meal orders','Cancellation cutoffs, incorrect-item handling, quality complaints, required evidence and refund methods must be confirmed by the business before an order is accepted.'),('Annual plan','The brief advertises a ₹1,00,000 advance, ₹12,000 annual subscription charge described as non-refundable, and ₹88,000 refund after successful completion of 12 months. These figures and eligibility rules require approval.'),('Early exit and deductions','Cancellation eligibility, service deductions, missed meals and early-exit calculations are unconfirmed. Do not assume the advertised annual refund applies to an early exit.'),('Refund timing','The brief refers to a minimum 30-day period for certain early refund requests. Its scope, start date and maximum timeline are not confirmed. No processing guarantee is made.'),('Request information','Call +91 7529973199 or +91 9990386825 for the approved agreement and request procedure. Do not send payment credentials through the enquiry form.')])}
pages={'index.html':('Healthy Eating. Smarter Living.',home),'menu.html':('Our Meals',menu),'subscriptions.html':('Subscription Plans',subscriptions),'refund-plan.html':('12-Month Plan Preview',refund),'contact.html':('Contact Us',contact),'about.html':('About Us',about),'how-it-works.html':('How It Works',how),'health-blog.html':('Healthy Living Journal',blog),'faq.html':('Frequently Asked Questions',faq),'meal-details.html':('Meal Details',pagehero('A CLOSER LOOK','Meet Your Next Meal','Explore the ingredients, then make it yours.')+'<section class="section container" id="meal-detail"></section>')}
